INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('60d29a09-1788-42bf-a986-7f2f0a448c53', 4, 2200, 'Frame 4 — On the whistle, every player stops with sole on ball.', $JSON$[{"id": "c1", "type": "cone", "x": 20, "y": 20, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 80, "y": 20, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c3", "type": "cone", "x": 20, "y": 80, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c4", "type": "cone", "x": 80, "y": 80, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "p1", "type": "player", "x": 35, "y": 30, "label": "1", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 35, "y": 30, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p2", "type": "player", "x": 50, "y": 30, "label": "2", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b2", "type": "ball", "x": 50, "y": 30, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p3", "type": "player", "x": 65, "y": 30, "label": "3", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b3", "type": "ball", "x": 65, "y": 30, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p4", "type": "player", "x": 35, "y": 70, "label": "4", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b4", "type": "ball", "x": 35, "y": 70, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p5", "type": "player", "x": 50, "y": 70, "label": "5", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b5", "type": "ball", "x": 50, "y": 70, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "p6", "type": "player", "x": 65, "y": 70, "label": "6", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b6", "type": "ball", "x": 65, "y": 70, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "t1", "type": "text", "geometry": {"x": 50, "y": 15, "text": "Stop! Sole on ball"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('e4190a85-05cb-488f-a3cb-aa5263710224', 0, 2400, 'Setup — full goal. Server (S) at left cone, shooter (A) at right cone, ball with S.', $JSON$[{"id": "g1", "type": "goal", "x": 50, "y": 8}, {"id": "c1", "type": "cone", "x": 30, "y": 55, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 70, "y": 55, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "s", "type": "player", "x": 30, "y": 55, "label": "S", "color": "#94a3b8", "rotation": 0, "size": 1}, {"id": "a", "type": "player", "x": 70, "y": 55, "label": "A", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 30, "y": 55, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "t1", "type": "text", "geometry": {"x": 50, "y": 75, "text": "Approach from an angle"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('e4190a85-05cb-488f-a3cb-aa5263710224', 1, 2400, 'Frame 1 — A makes a curved run; S plays a firm pass into A''s path.', $JSON$[{"id": "g1", "type": "goal", "x": 50, "y": 8}, {"id": "c1", "type": "cone", "x": 30, "y": 55, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 70, "y": 55, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "s", "type": "player", "x": 30, "y": 55, "label": "S", "color": "#94a3b8", "rotation": 0, "size": 1}, {"id": "a", "type": "player", "x": 60, "y": 45, "label": "A", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 45, "y": 45, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 30, "y": 55}, "to": {"x": 45, "y": 45}}, "style": {"color": "#fbbf24"}}, {"id": "a2", "type": "arrow-dashed", "geometry": {"from": {"x": 70, "y": 55}, "to": {"x": 60, "y": 45}}, "style": {"color": "#22c55e"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('e4190a85-05cb-488f-a3cb-aa5263710224', 2, 2400, 'Frame 2 — A takes one touch out of feet, away from standing foot.', $JSON$[{"id": "g1", "type": "goal", "x": 50, "y": 8}, {"id": "c1", "type": "cone", "x": 30, "y": 55, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 70, "y": 55, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "s", "type": "player", "x": 30, "y": 55, "label": "S", "color": "#94a3b8", "rotation": 0, "size": 1}, {"id": "a", "type": "player", "x": 48, "y": 40, "label": "A", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 50, "y": 38, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "t1", "type": "text", "geometry": {"x": 70, "y": 40, "text": "Touch out of feet"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('e4190a85-05cb-488f-a3cb-aa5263710224', 3, 2400, 'Frame 3 — Plant non-kicking foot beside the ball, lock ankle.', $JSON$[{"id": "g1", "type": "goal", "x": 50, "y": 8}, {"id": "c1", "type": "cone", "x": 30, "y": 55, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 70, "y": 55, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "s", "type": "player", "x": 30, "y": 55, "label": "S", "color": "#94a3b8", "rotation": 0, "size": 1}, {"id": "a", "type": "player", "x": 48, "y": 35, "label": "A", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 50, "y": 32, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "t1", "type": "text", "geometry": {"x": 70, "y": 32, "text": "Plant foot, lock ankle"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('e4190a85-05cb-488f-a3cb-aa5263710224', 4, 2400, 'Frame 4 — Driven shot low into the corner. Follow up the shot.', $JSON$[{"id": "g1", "type": "goal", "x": 50, "y": 8}, {"id": "c1", "type": "cone", "x": 30, "y": 55, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 70, "y": 55, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "s", "type": "player", "x": 30, "y": 55, "label": "S", "color": "#94a3b8", "rotation": 0, "size": 1}, {"id": "a", "type": "player", "x": 48, "y": 33, "label": "A", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 46, "y": 12, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 50, "y": 30}, "to": {"x": 46, "y": 12}}, "style": {"color": "#fbbf24"}}, {"id": "t1", "type": "text", "geometry": {"x": 65, "y": 12, "text": "Goal!"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('26104a51-898b-4de8-a2f1-5bf3159abb3b', 0, 2200, 'Setup — two cones placed diagonally. Player starts with ball at the side.', $JSON$[{"id": "c1", "type": "cone", "x": 40, "y": 40, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 60, "y": 60, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "p1", "type": "player", "x": 30, "y": 50, "label": "P", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 30, "y": 50, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "t1", "type": "text", "geometry": {"x": 50, "y": 15, "text": "Figure-8 around the cones"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('26104a51-898b-4de8-a2f1-5bf3159abb3b', 1, 2200, 'Frame 1 — Use inside of foot to come tightly around the first cone.', $JSON$[{"id": "c1", "type": "cone", "x": 40, "y": 40, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 60, "y": 60, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "p1", "type": "player", "x": 42, "y": 32, "label": "P", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 44, "y": 34, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 30, "y": 50}, "to": {"x": 44, "y": 34}}, "style": {"color": "#fbbf24"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('26104a51-898b-4de8-a2f1-5bf3159abb3b', 2, 2200, 'Frame 2 — Outside of foot for speed across the middle to the second cone.', $JSON$[{"id": "c1", "type": "cone", "x": 40, "y": 40, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 60, "y": 60, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "p1", "type": "player", "x": 55, "y": 48, "label": "P", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 55, "y": 48, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 44, "y": 34}, "to": {"x": 55, "y": 48}}, "style": {"color": "#fbbf24"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('26104a51-898b-4de8-a2f1-5bf3159abb3b', 3, 2200, 'Frame 3 — Inside of foot wraps tightly around cone 2.', $JSON$[{"id": "c1", "type": "cone", "x": 40, "y": 40, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 60, "y": 60, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "p1", "type": "player", "x": 62, "y": 68, "label": "P", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 62, "y": 68, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 55, "y": 48}, "to": {"x": 62, "y": 68}}, "style": {"color": "#fbbf24"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('26104a51-898b-4de8-a2f1-5bf3159abb3b', 4, 2200, 'Frame 4 — Return through the middle to complete the figure-8. Repeat continuously.', $JSON$[{"id": "c1", "type": "cone", "x": 40, "y": 40, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "c2", "type": "cone", "x": 60, "y": 60, "color": "#f97316", "rotation": 0, "size": 1}, {"id": "p1", "type": "player", "x": 40, "y": 55, "label": "P", "color": "#0ea5e9", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 40, "y": 55, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 62, "y": 68}, "to": {"x": 40, "y": 55}}, "style": {"color": "#fbbf24"}}, {"id": "t1", "type": "text", "geometry": {"x": 50, "y": 15, "text": "Both feet — keep touches small"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('bbf66975-bbea-46b2-849b-e5dd20e0a595', 0, 2400, 'Setup — GK in middle of full goal. Server stands 8m out with several balls.', $JSON$[{"id": "g1", "type": "goal", "x": 50, "y": 12}, {"id": "gk", "type": "player", "x": 50, "y": 18, "label": "GK", "color": "#22c55e", "rotation": 0, "size": 1}, {"id": "s", "type": "player", "x": 50, "y": 55, "label": "S", "color": "#94a3b8", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 50, "y": 55, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "b2", "type": "ball", "x": 46, "y": 58, "color": "#f5f5f5", "rotation": 0, "size": 1}, {"id": "b3", "type": "ball", "x": 54, "y": 58, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "t1", "type": "text", "geometry": {"x": 50, "y": 80, "text": "Low → Mid → High sequence"}}]$JSON$::jsonb);
INSERT INTO drill_frames (drill_id, position, duration_ms, notes, objects, annotations) VALUES ('bbf66975-bbea-46b2-849b-e5dd20e0a595', 1, 2400, 'Frame 1 — Server rolls a low ball; GK gets behind it and scoops into chest.', $JSON$[{"id": "g1", "type": "goal", "x": 50, "y": 12}, {"id": "gk", "type": "player", "x": 50, "y": 28, "label": "GK", "color": "#22c55e", "rotation": 0, "size": 1}, {"id": "s", "type": "player", "x": 50, "y": 55, "label": "S", "color": "#94a3b8", "rotation": 0, "size": 1}, {"id": "b1", "type": "ball", "x": 50, "y": 42, "color": "#f5f5f5", "rotation": 0, "size": 1}]$JSON$::jsonb, $JSON$[{"id": "a1", "type": "arrow-solid", "geometry": {"from": {"x": 50, "y": 55}, "to": {"x": 50, "y": 30}}, "style": {"color": "#fbbf24"}}, {"id": "t1", "type": "text", "geometry": {"x": 70, "y": 40, "text": "Long barrier — knee down"}}]$JSON$::jsonb);
